templates.Template:Equipment/styles.css:
.equip-table { width:100%; table-layout:auto; }
.equip-table th, .equip-table td { vertical-align:middle; text-align:center; }
.equip-table > caption{
  display: table-caption;       
  caption-side: top;
  width: 100% !important;
  max-width: 100%;
  box-sizing: border-box;
  white-space: normal;         
  overflow-wrap: anywhere;      
}

/* Appearance */
.equip-cell-img { width:72px; }
.equip-icon { display:block; margin:4px auto; image-rendering:pixelated; object-fit:contain; }

/* Name/desc */
.equip-cell-name { text-align:center; }
.e-desc { color:#cfd8dc; font-weight:400; font-size:13px; display:block; margin-top:2px; }

/* Slot/recipe */
.equip-cell-slot, .equip-cell-recipe { font-size:13px; }

/* Price */
.equip-cell-price { white-space:nowrap; }
.equip-cell-price .price-amt { color:#B2B277; font-weight:700; }

/* Stats cell */
.equip-cell-stats{
  padding:8px 10px;
  font-size:13px;
  line-height:1.2;
  min-width:240px;
  white-space:normal !important;
}

.equip-stats{
  display:grid !important;
  grid-template-columns: auto auto;   /* label | value */
  column-gap:10px;                    /* ← space between label and value */
  row-gap:6px;                        /* space between rows */
  justify-content:center;
  align-items:center;
  margin:0;
}

.equip-stat { display:contents; }     /* let label+value occupy the two grid cells */

.stat-label{
  justify-self:end;                   /* right-align labels */
  font-weight:700;
}

.stat-val{
  justify-self:start;                 /* left-align values */
  font-weight:700;
  color:#fff;
}

/* 6★ divider */
.equip-6star{
  margin:8px auto 6px;
  text-align:center;
  opacity:.85;
  border-top:1px solid #ffffff30;
  padding-top:4px;
  font-size:12px;
  letter-spacing:.5px;
  width:90%;
}

templates.Template:Countdown/styles.css:
.countdown-card{position:relative;isolation:isolate;display:flex;flex-direction:column;justify-content:flex-end;min-height:220px;border-radius:12px;overflow:hidden;border:1px solid rgba(255,255,255,.08);background:#111;background-image:var(--bg);background-size:cover;background-position:center;box-shadow:0 6px 18px rgba(0,0,0,.18);}
.countdown-card__mask{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,0) 5%,rgba(0,0,0,.28) 35%,rgba(0,0,0,.75) 75%,rgba(0,0,0,.95) 100%);z-index:0;}
.countdown-card__label{position:absolute;top:10px;left:10px;z-index:2;font-weight:700;font-size:.85rem;padding:6px 10px;border-radius:999px;color:#0b0b0b;background:linear-gradient(90deg,var(--a1,#22c55e),var(--a2,#34d399),var(--a3,#84cc16));box-shadow:0 2px 8px rgba(0,0,0,.25);}
.countdown-card__body{position:relative;z-index:1;color:#fff;width:100%;box-sizing:border-box;padding:28px 16px 16px 16px;} /* more top padding so header clears pill */
.countdown-card__header{font-weight:800;font-size:1.25rem;line-height:1.2;text-shadow:0 2px 10px rgba(0,0,0,.5);margin-bottom:10px;}
.countdown-card__timer{display:flex;align-items:baseline;justify-content:flex-start;gap:10px;margin:6px 0 8px 0;padding-bottom:8px;border-bottom:1px solid rgba(255,255,255,.12);}
.countdown-card__tag{opacity:.9;font-weight:700;letter-spacing:.2px;}
.countdown-card__clock{font-weight:800;font-size:1.05rem;}
.countdown-card__list{margin:10px 0 0 18px;padding:0;}
.countdown-card__list li{margin:4px 0;line-height:1.25;color:#e8eaed;}
@media (max-width:640px){.countdown-card{min-height:200px}.countdown-card__header{font-size:1.1rem}}

.countdown-card__clock,
.countdown-card__clock *{background:transparent !important;border:0 !important;box-shadow:none !important;margin:0 !important;padding:0 !important;}
.countdown-card__clock table,
.countdown-card__clock tbody,
.countdown-card__clock tr,
.countdown-card__clock td,
.countdown-card__clock .countdown,
.countdown-card__clock #countdown,
.countdown-card__clock #countDownClock,
.countdown-card__clock .countDownClock{background:transparent !important;border:0 !important;margin:0 !important;padding:0 !important;}
.countdown-card__clock,
.countdown-card__clock .countdown,
.countdown-card__clock #countdown,
.countdown-card__clock #countDownClock,
.countdown-card__clock .countDownClock{color:#fff !important;font-family:inherit !important;font-weight:800 !important;font-size:1.05rem !important;letter-spacing:.2px;}

