  margin-top: 3px;
  margin-bottom: 3px;
  margin-left: 11px;
  border-left: 2px solid #282830;
}

div.dialogue > dl,
div.dialogue td > dl {
  margin-bottom: 10px;
  border-left: none;
}

.dialogue dt {
  font-weight: normal;
  font-style: italic;
  font-size: .85em;
  font-family: revert;
  margin: 0;
  opacity: 0.75;
}

.dialogue dt i { font-style: normal; }

.dialogue hr {
  border-color: #52566b;
  border-bottom: 0;
}

.npc-choice {
  --choice-accent: #6aa3ff;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  margin: 6px 0 2px;
  max-width: 640px;
  background: rgba(40, 40, 48, .6);
  border: 1px solid rgba(255, 255, 255, .06);
  border-left: 4px solid var(--choice-accent);
  border-radius: 6px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
  transition: transform .08s ease, box-shadow .15s ease, background .2s ease;
}

.npc-choice:hover {
  transform: translateX(2px);
  background: rgba(40, 40, 48, .75);
  box-shadow: 0 4px 14px rgba(0,0,0,.2);
}

.npc-choice-icon {
  display: inline-flex;
